-- The cast corpus's one table T: every numeric width at its minimum and maximum (signed,
-- unsigned, 32-bit and 64-bit float, DECIMAL), a DOUBLE column with -0.0, a DOUBLE column
-- of infinities, NaN and a huge value, a BOOLEAN, strings that look like other types,
-- a DATE and a TIMESTAMP with a sub-second field, and one all-NULL row. Floats and
-- special values are quoted literals cast to their type so the sign of zero survives.
CREATE TABLE T (k BIGINT, i8 TINYINT, i16 SMALLINT, i32 INTEGER, i64 BIGINT, u8 UTINYINT, u32 UINTEGER, u64 UBIGINT, f32 FLOAT, f64 DOUBLE, fs DOUBLE, dec DECIMAL(18,4), b BOOLEAN, s VARCHAR, d DATE, ts TIMESTAMP);
